  const sourceSystem = String(lead.sourceSystem || 'n8n-baidu-lead-staging').trim();
  const externalLeadId = String(lead.externalLeadId || '').trim();
  const companyName = String(lead.companyName || '').trim();
  if (!externalLeadId || !companyName) throw new Error(`LEAD_SOURCE_INVALID_${index}`);
  const idempotencyKey = String(lead.idempotencyKey || `lead-v1-${stableDigest(`lead-idempotency-v1|${sourceSystem}|${externalLeadId}`)}`).trim();
  if (idempotencyKey.length < 16 || idempotencyKey.length > 191 || !/^[A-Za-z0-9][A-Za-z0-9._:-]*$/.test(idempotencyKey)) throw new Error(`LEAD_IDEMPOTENCY_INVALID_${index}`);
  if (lead.requestId !== undefined && String(lead.requestId).trim() === idempotencyKey) throw new Error(`LEAD_IDEMPOTENCY_INVALID_${index}`);
  return { json: { ...lead, companyName, source: lead.source || 'BAIDU_SEARCH', sourceSystem, externalLeadId, idempotencyKey } };
});

const response = $json;
