const stableDigest = (input) => {
  const fnv64 = (offset) => {
    let hash = offset;
    for (let index = 0; index < input.length; index += 1) { hash ^= BigInt(input.charCodeAt(index)); hash = BigInt.asUintN(64, hash * 1099511628211n); }
    return hash.toString(16).padStart(16, '0');
  };
