  const entry = page[index];
  if (!entry?.sourceLead?.idempotencyKey || entry.sourceLead.idempotencyKey === entry.sourceLead.requestId || !Number.isInteger(entry?.score?.aiScore) || entry.score.aiScore < 0 || entry.score.aiScore > 100) throw new Error(`LEAD_SCORE_PAGE_INVALID_${index}`);
